{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 노외주차장 전체 시설면적 중 부대시설(상가 등) 설치 비율",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제16조 제3항에 따르면, 노외주차장의 총 시설면적 중 부대시설이 차지하는 비율은 30퍼센트 이내로 한다. 다만, 법 제12조제6항에 따른 노외주차장 설치 제한지역에 해당하는 경우에는 10퍼센트 이내로 한다.",
          "b_ids": "주차장:제16조제3항, 주차장:제16조제3항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
